122	                if (claim.getSettledDue() != null || claim.getBoundDue() != null) {
123	                    anyDue = true;
124	                }
125	                Optional<BigDecimal> claimDue = dueOf(sheet, sheetRates, person, claim);
126	                if (isOverdue(sheet, person, claim, today)) {
127	                    overdueCount++;
128	                }
129	                if (claimDue.isPresent()) {
130	                    due = due.add(claimDue.get());
131	                    // A correction leaves the score's settled figure alone.
132	                    if (claim.getStatus() == ClaimStatus.SETTLED && claim.getCorrects() == null) {
133	                        settled = settled.add(claimDue.get());
134	                    }
135	                    if (isOverdue(sheet, person, claim, today)) {
136	                        overdue = overdue.add(claimDue.get());
137	                    }
138	                    // A due under a grade the person had on an earlier date counts too.
139	                    if (today != null && !claim.getDate().isAfter(today)) {
140	                        anyDue = true;
141	                    }
142	                }
143	            }
144	            claimedTotal = claimedTotal.add(claimed);
145	            overdues.add(overdue);
146	            if (anyDue && sheet != null) {
147	                due = sheet.capped(due);
148	            }
149	            if (anyDue) {
150	                dues.add(due);
151	            }
152	            figures.put(person.getId(), new Figures(person.getName(), shown(claimed), anyDue ? shown(due) : "n/a",
153	                    shown(overdue), today == null ? null : person.gradeOn(today), scoreOf(settled, overdueCount)));
154	        }
155	        return new Snapshot(figures, shown(claimedTotal), shown(trimmedSum(dues)), shown(trimmedSum(overdues)));
156	    }
