181	    /** The figures of the sheets, each sheet's as that sheet shows them, added up. */
182	    private Consolidated figuresOf(List<String> sheetIds) {
183	        int count = 0;
184	        BigDecimal due = zero();
185	        BigDecimal overdue = zero();
186	        Map<String, BigDecimal> gradeDues = new TreeMap<>();
187	        Map<String, Integer> statuses = new TreeMap<>();
188	        List<Member> members = new ArrayList<>();
189	        for (String id : sheetIds) {
190	            Snapshot figures = snapshot(id);
191	            count += figures.people().size();
192	            Map<Long, List<String>> namesOf = new LinkedHashMap<>();
193	            for (PersonAlias alias : aliases.findBySheetId(id)) {
194	                namesOf.computeIfAbsent(alias.getPersonId(), p -> new ArrayList<>()).add(alias.getAliasKey());
195	            }
196	            figures.people().forEach((personId, theirs) -> {
197	                List<String> names = new ArrayList<>(List.of(Person.key(theirs.name())));
198	                names.addAll(namesOf.getOrDefault(personId, List.of()));
199	                members.add(new Member(theirs.dueTotal(), theirs.overdueTotal(), names));
200	            });
201	            due = due.add(new BigDecimal(figures.dueTotal()));
202	            overdue = overdue.add(new BigDecimal(figures.overdueTotal()));
203	            for (Person person : people.findBySheetIdOrderByPositionAscIdAsc(id)) {
204	                Figures theirs = figures.people().get(person.getId());
205	                if (person.isRetired() || theirs == null || theirs.grade() == null || theirs.dueTotal().equals("n/a")) {
206	                    continue;
207	                }
208	                gradeDues.merge(theirs.grade(), new BigDecimal(theirs.dueTotal()), BigDecimal::add);
209	            }
210	            for (Claim claim : claims.findBySheetIdOrderByIdDesc(id)) {
211	                statuses.merge(claim.getStatus().name(), 1, Integer::sum);
212	            }
213	        }
214	        return new Consolidated(count, shown(due), shown(overdue), shownAll(gradeDues), statuses, members);
215	    }
