217	    /**
218	     * The figures of the sheet and its descendants: the people counted once over the tree (people whose names or
219	     * aliases match, as names are compared, are one person); the due-total and overdue-total trimmed once over every
220	     * person's figure of the tree; per grade and per status, each sheet's added up. While the request shows the sheet
221	     * as of a date, every sheet of the tree is as it stood at the end of that date, with the date as its today.
222	     */
223	    public Consolidated consolidatedFigures(String sheetId) {
224	        Consolidated own = figuresOf(List.of(sheetId));
225	        Consolidated descendants = descendantFigures(sheetId);
226	        Map<String, BigDecimal> gradeDues = new TreeMap<>();
227	        own.gradeDueTotals().forEach((grade, total) -> gradeDues.merge(grade, new BigDecimal(total), BigDecimal::add));
228	        descendants.gradeDueTotals()
229	                .forEach((grade, total) -> gradeDues.merge(grade, new BigDecimal(total), BigDecimal::add));
230	        Map<String, Integer> statuses = new TreeMap<>(own.statusCounts());
231	        descendants.statusCounts().forEach((status, n) -> statuses.merge(status, n, Integer::sum));
232	        List<Member> members = new ArrayList<>(own.members());
233	        members.addAll(descendants.members());
234	        List<BigDecimal> dues = members.stream().map(Member::dueTotal).filter(d -> !d.equals("n/a"))
235	                .map(BigDecimal::new).toList();
236	        List<BigDecimal> overdues = members.stream().map(Member::overdueTotal).map(BigDecimal::new).toList();
237	        return new Consolidated(distinctPeople(members), shown(trimmedSum(dues)), shown(trimmedSum(overdues)),
238	                shownAll(gradeDues), statuses, members);
239	    }
