242	     * This sheet compared with another, one line per grade of this sheet: {@code <grade> <this sheet's due-total>
243	     * <the other sheet's>}, each the summary's due-total for the grade (0.00 for a grade with no one on it); no lines
244	     * when the other sheet does not exist. It changes nothing.
245	     */
246	    public List<String> compare(String sheetId, String otherId) {
247	        if (otherId.isBlank() || !sheets.existsById(otherId)) {
248	            return List.of();
249	        }
250	        Map<String, String> ours = figuresOf(List.of(sheetId)).gradeDueTotals();
251	        Map<String, String> theirs = figuresOf(List.of(otherId)).gradeDueTotals();
252	        return SettingService.GRADES.stream()
253	                .map(grade -> grade + " " + ours.getOrDefault(grade, "0.00") + " " + theirs.getOrDefault(grade, "0.00"))
254	                .toList();
