257	    /** How many people the members are, those whose names or aliases match (as names are compared) being one. */
258	    private static int distinctPeople(List<Member> members) {
259	        int[] parent = new int[members.size()];
260	        Map<String, Integer> firstWith = new LinkedHashMap<>();
261	        int count = members.size();
262	        for (int i = 0; i < members.size(); i++) {
263	            parent[i] = i;
264	            for (String name : members.get(i).names()) {
265	                Integer other = firstWith.putIfAbsent(name, i);
266	                if (other != null) {
267	                    int a = top(parent, i);
268	                    int b = top(parent, other);
269	                    if (a != b) {
270	                        parent[a] = b;
271	                        count--;
272	                    }
273	                }
274	            }
275	        }
276	        return count;
277	    }
278	
279	    private static int top(int[] parent, int i) {
280	        while (parent[i] != i) {
281	            i = parent[i];
282	        }
283	        return i;
284	    }
