286	    /**
287	     * Every person on the sheet and the other sheets of its tree (its topmost ancestor and all that one's descendants)
288	     * whose name or an alias contains the text, case ignored, each as {@code <sheet id> <name> <due-total>} with the
289	     * due-total as that sheet shows it: the sheet's people first in list order, then the other sheets' by sheet id.
290	     */
291	    public List<String> search(String sheetId, String text) {
292	        String wanted = text.toLowerCase(Locale.ROOT);
293	        List<String> others = new ArrayList<>();
294	        String root = root(sheetId);
295	        if (!root.equals(sheetId)) {
296	            others.add(root);
297	        }
298	        for (String id : descendants(root)) {
299	            if (!id.equals(sheetId)) {
300	                others.add(id);
301	            }
302	        }
303	        others.sort(null);
304	        List<String> order = new ArrayList<>(List.of(sheetId));
305	        order.addAll(others);
306	        List<String> lines = new ArrayList<>();
307	        for (String id : order) {
308	            Map<Long, List<String>> aliasesOf = new LinkedHashMap<>();
309	            for (PersonAlias alias : aliases.findBySheetId(id)) {
310	                aliasesOf.computeIfAbsent(alias.getPersonId(), p -> new ArrayList<>()).add(alias.getAlias());
311	            }
312	            Map<Long, Figures> figures = snapshot(id).people();
313	            for (Map.Entry<Long, Figures> entry : figures.entrySet()) {
314	                Figures person = entry.getValue();
315	                boolean matches = person.name().toLowerCase(Locale.ROOT).contains(wanted)
316	                        || aliasesOf.getOrDefault(entry.getKey(), List.of()).stream()
317	                                .anyMatch(alias -> alias.toLowerCase(Locale.ROOT).contains(wanted));
318	                if (matches) {
319	                    lines.add(id + " " + named(person) + " " + person.dueTotal());
320	                }
321	            }
322	        }
323	        return lines;
324	    }
