331	    /**
332	     * The ids of the sheet's descendants, as {@link #descendants(String)}. While the request shows the sheet as of a
333	     * date, each is first put back as it stood at the end of that date, with the date as its today, for the request's
334	     * transaction alone (which the as-of view rolls back).
335	     */
336	    private List<String> descendantsAsOf(String sheetId) {
337	        List<String> ids = descendants(sheetId);
338	        LocalDate asOf = AsOfContext.current();
339	        if (asOf != null && !ids.isEmpty()) {
340	            entities.flush();
341	            for (String id : ids) {
342	                snapshots.restore(id, asOf);
343	            }
344	            // The sheets read to find them are stale now: read them afresh.
345	            entities.clear();
346	        }
347	        return ids;
348	    }
