350	    /** The sheet's topmost ancestor (the sheet itself with no parent); a parent loop stops where it comes back. */
351	    private String root(String sheetId) {
352	        List<String> seen = new ArrayList<>(List.of(sheetId));
353	        String top = sheetId;
354	        String parent = sheets.findById(sheetId).map(Sheet::getParent).orElse(null);
355	        while (parent != null && !seen.contains(parent)) {
356	            seen.add(parent);
357	            top = parent;
358	            parent = sheets.findById(parent).map(Sheet::getParent).orElse(null);
359	        }
360	        return top;
361	    }
362	
363	    /** The ids of the sheet's descendants, each once, nearest first; a parent loop never brings back the sheet. */
364	    private List<String> descendants(String sheetId) {
365	        List<String> seen = new ArrayList<>(List.of(sheetId));
366	        for (int i = 0; i < seen.size(); i++) {
367	            for (Sheet child : sheets.findByParentOrderByIdAsc(seen.get(i))) {
368	                if (!seen.contains(child.getId())) {
369	                    seen.add(child.getId());
370	                }
371	            }
372	        }
373	        return seen.subList(1, seen.size());
374	    }
