380	    /**
381	     * What the screen would show if the grade had the percent on every date, changing nothing: of the OPEN and PENDING
382	     * claims whose person had the grade on the claim's date, how many would show a different due, and the sum of each
383	     * new due minus its current one (an n/a due counting as 0.00). A claim bound by a statement keeps its stated due.
384	     */
385	    public RatePreview preview(String sheetId, String grade, BigDecimal pct) {
386	        Sheet sheet = sheets.findById(sheetId).orElse(null);
387	        List<List<Rate>> sheetRates = rateChain(sheetId);
388	        List<Rate> own = new ArrayList<>(sheetRates.get(0).stream().filter(r -> !r.getGrade().equals(grade)).toList());
389	        own.add(new Rate(sheetId, grade, null, pct));
390	        List<List<Rate>> candidate = new ArrayList<>(sheetRates);
391	        candidate.set(0, own);
392	        Map<Long, Person> byId = new LinkedHashMap<>();
393	        for (Person person : people.findBySheetIdOrderByPositionAscIdAsc(sheetId)) {
394	            byId.put(person.getId(), person);
395	        }
396	        int count = 0;
397	        BigDecimal diff = zero();
398	        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
399	            Person person = byId.get(claim.getPersonId());
400	            if (person == null || !claim.getStatus().isOpen() || !grade.equals(person.gradeOn(claim.getDate()))) {
401	                continue;
402	            }
403	            BigDecimal now = dueOf(sheet, sheetRates, person, claim).map(RollupService::cents).orElse(null);
404	            BigDecimal then = dueOf(sheet, candidate, person, claim).map(RollupService::cents).orElse(null);
405	            if (Objects.equals(now, then)) {
406	                continue;
407	            }
408	            count++;
409	            diff = diff.add(then == null ? zero() : then).subtract(now == null ? zero() : now);
410	        }
411	        return new RatePreview(count, shown(diff));
412	    }
