418	    /** The figures added up, leaving out the single highest and the single lowest when there are three or more. */
419	    private static BigDecimal trimmedSum(List<BigDecimal> figures) {
420	        List<BigDecimal> kept = new ArrayList<>(figures);
421	        if (kept.size() >= 3) {
422	            kept.sort(null);
423	            kept = kept.subList(1, kept.size() - 1);
424	        }
425	        return kept.stream().reduce(zero(), BigDecimal::add);
426	    }
