428	    /**
429	     * Each person's due-total of the dates from and to, both inclusive, by person id for every person on the sheet, as
430	     * the screen shows a person's for a period: the dues as shown now of their claims due by a date in them that were OPEN,
431	     * PENDING or SETTLED at the end of the to-date by their status log, skipping those with no due and the open ones
432	     * their retirement leaves out; 0.00 with none.
433	     */
434	    public Map<Long, BigDecimal> dueTotalsBetween(String sheetId, LocalDate from, LocalDate to) {
435	        Sheet sheet = sheets.findById(sheetId).orElse(null);
436	        LocalDate today = sheet == null ? null : sheet.getToday();
437	        List<List<Rate>> sheetRates = rateChain(sheetId);
438	        Map<Long, Person> byId = new LinkedHashMap<>();
439	        Map<Long, BigDecimal> totals = new LinkedHashMap<>();
440	        for (Person person : people.findBySheetIdOrderByPositionAscIdAsc(sheetId)) {
441	            byId.put(person.getId(), person);
442	            totals.put(person.getId(), zero());
443	        }
444	        Map<Long, List<ClaimLog>> logOf = new LinkedHashMap<>();
445	        for (ClaimLog line : logs.findBySheetIdOrderByIdAsc(sheetId)) {
446	            logOf.computeIfAbsent(line.getClaimId(), id -> new ArrayList<>()).add(line);
447	        }
448	        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
449	            Person person = byId.get(claim.getPersonId());
450	            ClaimStatus status = statusOn(claim, logOf.getOrDefault(claim.getId(), List.of()), to);
451	            if (person == null || !person.countsAsOf(claim, status, today) || claim.getDueBy().isBefore(from)
452	                    || claim.getDueBy().isAfter(to)) {
453	                continue;
454	            }
455	            dueOf(sheet, sheetRates, person, claim).ifPresent(due -> totals.merge(person.getId(), due, BigDecimal::add));
456	        }
457	        totals.replaceAll((id, total) -> total.setScale(2, RoundingMode.HALF_EVEN));
458	        return totals;
459	    }
