461	    /**
462	     * Each person's carried figure for the period, by person id for every person on the sheet, as the screen shows it
463	     * while the period is open: the dues as shown now of their claims due by a date in one of the periods that ends
464	     * before it starts that were OPEN or PENDING at the end of its to-date by their status log and count then, skipping
465	     * those with no due, plus their opening balance for it; 0.00 with none.
466	     */
467	    public Map<Long, BigDecimal> carriedInto(String sheetId, List<Period> periods, Period period) {
468	        Sheet sheet = sheets.findById(sheetId).orElse(null);
469	        LocalDate today = sheet == null ? null : sheet.getToday();
470	        List<List<Rate>> sheetRates = rateChain(sheetId);
471	        Map<Long, Person> byId = new LinkedHashMap<>();
472	        Map<Long, BigDecimal> totals = new LinkedHashMap<>();
473	        for (Person person : people.findBySheetIdOrderByPositionAscIdAsc(sheetId)) {
474	            byId.put(person.getId(), person);
475	            totals.put(person.getId(), zero());
476	        }
477	        Map<Long, List<ClaimLog>> logOf = new LinkedHashMap<>();
478	        for (ClaimLog line : logs.findBySheetIdOrderByIdAsc(sheetId)) {
479	            logOf.computeIfAbsent(line.getClaimId(), id -> new ArrayList<>()).add(line);
480	        }
481	        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
482	            Person person = byId.get(claim.getPersonId());
483	            if (person == null || claim.getDueBy() == null) {
484	                continue;
485	            }
486	            Optional<Period> from = periods.stream().filter(p -> p.contains(claim.getDueBy())).findFirst();
487	            if (from.isEmpty() || !from.get().getToDate().isBefore(period.getFromDate())) {
488	                continue;
489	            }
490	            ClaimStatus status = statusOn(claim, logOf.getOrDefault(claim.getId(), List.of()), period.getToDate());
491	            if (status == null || !status.isOpen() || !person.countsAsOf(claim, status, today)) {
492	                continue;
493	            }
494	            dueOf(sheet, sheetRates, person, claim).ifPresent(due -> totals.merge(person.getId(), due, BigDecimal::add));
495	        }
496	        period.getPersonOpenings().forEach((id, opening) -> totals.computeIfPresent(id, (k, total) -> total.add(opening)));
497	        totals.replaceAll((id, total) -> total.setScale(2, RoundingMode.HALF_EVEN));
498	        return totals;
499	    }
