536	    /**
537	     * Record, once the transaction commits, a ROLLUP line for each person whose figures moved since the snapshot (a
538	     * person new since then counting as moved), then a TOTALS line when any of the sheet's three totals moved.
539	     */
540	    public void recordChanges(String sheetId, String user, Snapshot before) {
541	        Snapshot after = snapshot(sheetId);
542	        for (Map.Entry<Long, Figures> entry : after.people().entrySet()) {
543	            Figures was = before.people().get(entry.getKey());
544	            Figures now = entry.getValue();
545	            if (was != null && was.claimed().equals(now.claimed()) && was.dueTotal().equals(now.dueTotal())
546	                    && was.overdueTotal().equals(now.overdueTotal())) {
547	                continue;
548	            }
549	            audit.recordOnCommit("ROLLUP sheet=" + sheetId + " by=" + user + " person=" + now.name()
550	                    + " claimed=" + now.claimed() + " due-total=" + now.dueTotal()
551	                    + " overdue-total=" + now.overdueTotal());
552	        }
553	        if (!Objects.equals(before.claimedTotal(), after.claimedTotal())
554	                || !Objects.equals(before.dueTotal(), after.dueTotal())
555	                || !Objects.equals(before.overdueTotal(), after.overdueTotal())) {
556	            audit.recordOnCommit("TOTALS sheet=" + sheetId + " by=" + user + " claimed-total=" + after.claimedTotal()
557	                    + " due-total=" + after.dueTotal() + " overdue-total=" + after.overdueTotal());
558	        }
559	        recordAlerts(sheetId, user, before, after);
560	    }
