562	    /**
563	     * Record, once the transaction commits, an ALERT line, in list order, for each person whose due-total went from at
564	     * or below the sheet's alert threshold (or none, or n/a) to above it; nothing while the threshold is off.
565	     */
566	    private void recordAlerts(String sheetId, String user, Snapshot before, Snapshot after) {
567	        BigDecimal threshold = sheets.findById(sheetId).map(Sheet::getAlertThreshold).orElse(null);
568	        if (threshold == null) {
569	            return;
570	        }
571	        for (Map.Entry<Long, Figures> entry : after.people().entrySet()) {
572	            Figures was = before.people().get(entry.getKey());
573	            Figures now = entry.getValue();
574	            if (above(now, threshold) && !above(was, threshold)) {
575	                audit.recordOnCommit("ALERT sheet=" + sheetId + " by=" + user + " name=" + now.name()
576	                        + " due-total=" + now.dueTotal());
577	            }
578	        }
579	    }
