586	    /**
587	     * Record a ROLLUP line for every person on the sheet, in list order, then a TOTALS line, then an ALERT line for
588	     * each above the alert threshold.
589	     */
590	    public void recordAll(String sheetId, String user) {
591	        Snapshot now = snapshot(sheetId);
592	        for (Figures person : now.people().values()) {
593	            audit.recordOnCommit("ROLLUP sheet=" + sheetId + " by=" + user + " person=" + person.name()
594	                    + " claimed=" + person.claimed() + " due-total=" + person.dueTotal()
595	                    + " overdue-total=" + person.overdueTotal());
596	        }
597	        audit.recordOnCommit("TOTALS sheet=" + sheetId + " by=" + user + " claimed-total=" + now.claimedTotal()
598	                + " due-total=" + now.dueTotal() + " overdue-total=" + now.overdueTotal());
599	        recordAlerts(sheetId, user, new Snapshot(Map.of(), null, null, null), now);
600	    }
601	
602	    /**
603	     * As on the screen: the settled due, else the stated due (late charge included, as it was shown when bound), else
604	     * the amount at the rate on the claim's date, rounded as the sheet's policy date has the claim round, raised to the
605	     * floor in force on the claim's date, with the late charge of an overdue claim worked out on that and added on top; a correction has
606	     * neither floor nor late charge.
607	     */
608	    private static Optional<BigDecimal> dueOf(Sheet sheet, List<List<Rate>> sheetRates, Person person, Claim claim) {
609	        if (claim.getSettledDue() != null) {
610	            return Optional.of(claim.getSettledDue());
611	        }
612	        Optional<BigDecimal> figure = claim.isBound() ? Optional.ofNullable(claim.getStatedDue())
613	                : rateOn(sheetRates, person.gradeOn(claim.getDate()), claim.getDate(), claim.rateStamp())
614	                        .map(Rate::getPct)
615	                        .map(pct -> sheet == null
616	                                ? claim.getAmount().multiply(pct).movePointLeft(2).setScale(2, RoundingMode.HALF_EVEN)
617	                                : sheet.rateStep(claim.getAmount(), pct, claim.getDate(), claim.getRoundingDate()));
618	        return sheet == null || claim.isBound() || claim.isCorrection() ? figure
619	                : figure.map(f -> sheet.liveDue(f, claim.getStatus().isOpen() && !claim.isWaived(),
620	                        sheet.overdueBy(claim.getDueBy(), person.gradeOn(claim.getDate()), claim.getDate()),
621	                        claim.getDate()));
622	    }
623	
624	    /**
625	     * The status the claim had at the end of the date by its log (oldest first): its last line logged on or before the
626	     * date; null when it has lines but none by then. With no log at all, its status now.
627	     */
628	    private static ClaimStatus statusOn(Claim claim, List<ClaimLog> log, LocalDate date) {
629	        if (log.isEmpty()) {
630	            return claim.getStatus();
631	        }
632	        ClaimStatus found = null;
633	        for (ClaimLog line : log) {
634	            if (!line.getDate().isAfter(date)) {
635	                found = line.getStatus();
636	            }
637	        }
638	        return found;
639	    }
640	
641	    /**
642	     * As on the screen: an OPEN or PENDING claim whose due-by, plus the grace days its person's grade has on its date,
643	     * is before the sheet's today.
644	     */
645	    private static boolean isOverdue(Sheet sheet, Person person, Claim claim, LocalDate today) {
646	        return claim.getStatus().isOpen() && today != null && claim.getDueBy() != null
647	                && sheet.overdueBy(claim.getDueBy(), person.gradeOn(claim.getDate()), claim.getDate()).isBefore(today);
648	    }
649	
650	    /** How many levels of parent sheets a grade with no rate in force on a sheet falls back on. */
651	    public static final int PARENT_LEVELS = 3;
652	
653	    /**
654	     * The sheet's rates, then its parent's, its parent's parent's and so on up to {@link #PARENT_LEVELS} levels up, in
655	     * grade order then by from-date; then, when the sheet was cloned, likewise those of the sheet it was cloned from and
656	     * its parents, then of that sheet's source and so on: the rates a grade's rate on a date is looked for in, nearest
657	     * first, each sheet once. While the request shows the sheet as of a date, the other sheets' rates are as they stood
658	     * then.
659	     */
660	    public List<List<Rate>> rateChain(String sheetId) {
661	        return rateChain(sheetId, AsOfContext.current());
662	    }
663	
664	    /**
665	     * As {@link #rateChain(String)}, with the other sheets' rates as they stood at the end of {@code asOf} (null: as
666	     * they are now).
667	     */
668	    public List<List<Rate>> rateChain(String sheetId, LocalDate asOf) {
669	        List<List<Rate>> chain = new ArrayList<>();
670	        chain.add(withOlder(rates.findBySheetIdOrderByGradeAscFromDateAscIdAsc(sheetId)));
671	        List<String> seen = new ArrayList<>(List.of(sheetId));
672	        Sheet at = sheets.findById(sheetId).orElse(null);
673	        while (at != null) {
674	            String parent = at.getParent();
675	            for (int levels = 0; parent != null && levels < PARENT_LEVELS && !seen.contains(parent); levels++) {
676	                seen.add(parent);
677	                chain.add(ratesOf(parent, asOf));
678	                parent = sheets.findById(parent).map(Sheet::getParent).orElse(null);
679	            }
680	            String source = at.getSource();
681	            if (source == null || seen.contains(source)) {
682	                break;
683	            }
684	            seen.add(source);
685	            chain.add(ratesOf(source, asOf));
686	            at = sheets.findById(source).orElse(null);
687	        }
688	        return chain;
689	    }
690	
691	    /** Another sheet's rates in the chain, as they stood at the end of {@code asOf} (null: as they are now). */
692	    private List<Rate> ratesOf(String sheetId, LocalDate asOf) {
693	        return asOf == null ? withOlder(rates.findBySheetIdOrderByGradeAscFromDateAscIdAsc(sheetId))
694	                : ratesAsOf(sheetId, asOf);
695	    }
696	
697	    /**
698	     * The rates, each forward-only one with its older versions read with it, so a claim added before it was saved
699	     * falls back on the version it saw.
700	     */
701	    public List<Rate> withOlder(List<Rate> sheetRates) {
702	        for (Rate rate : sheetRates) {
703	            if (rate.getForwardAfter() != null) {
704	                rate.setOlder(rateVersions.findByRateIdOrderByVersionAsc(rate.getId()));
705	            }
706	        }
707	        return sheetRates;
708	    }
709	
710	    /** The sheet's rates as they stood at the end of {@code asOf}, by its rate log, in grade order then by from-date. */
711	    private List<Rate> ratesAsOf(String sheetId, LocalDate asOf) {
712	        Map<String, List<Rate>> now = new TreeMap<>();
713	        for (Rate rate : withOlder(rates.findBySheetIdOrderByGradeAscFromDateAscIdAsc(sheetId))) {
714	            now.computeIfAbsent(rate.getGrade(), g -> new ArrayList<>()).add(rate);
715	        }
716	        Map<String, List<RateLog>> set = new TreeMap<>();
717	        for (RateLog log : rateLogs.findBySheetIdOrderByIdAsc(sheetId)) {
718	            set.computeIfAbsent(log.getGrade(), g -> new ArrayList<>()).add(log);
719	            now.computeIfAbsent(log.getGrade(), g -> new ArrayList<>());
720	        }
721	        List<Rate> stood = new ArrayList<>();
722	        for (Map.Entry<String, List<Rate>> grade : now.entrySet()) {
723	            stood.addAll(RateLog.stood(sheetId, grade.getKey(), grade.getValue(),
724	                    set.getOrDefault(grade.getKey(), List.of()), asOf).stream()
725	                    .sorted(Comparator.comparing(Rate::getFromDate, Comparator.nullsFirst(Comparator.naturalOrder())))
726	                    .toList());
727	        }
728	        return stood;
729	    }
730	
731	    /**
732	     * The grade's rate in force on the date: the sheet's own, else the first in force further along its rate chain
733	     * (its parents', then its source's; nearest first); empty when none is.
734	     */
735	    public static Optional<Rate> rateOn(List<List<Rate>> chain, String grade, LocalDate date) {
736	        return rateOn(chain, grade, date, null);
737	    }
738	
739	    /**
740	     * As {@link #rateOn(List, String, LocalDate)}, for the claim with the stamp: leaving out the forward-only rates
741	     * saved before it was added, each falling back on its newest older version the claim sees (null: without regard
742	     * to forward-only rates).
743	     */
744	    public static Optional<Rate> rateOn(List<List<Rate>> chain, String grade, LocalDate date, Long stamp) {
745	        for (List<Rate> level : chain) {
746	            Optional<Rate> found = rateOnLevel(level, grade, date, stamp);
747	            if (found.isPresent()) {
748	                return found;
749	            }
750	        }
751	        return Optional.empty();
752	    }
753	
754	    private static Optional<Rate> rateOnLevel(List<Rate> sheetRates, String grade, LocalDate date, Long stamp) {
755	        return sheetRates.stream()
756	                .filter(r -> r.getGrade().equals(grade))
757	                .flatMap(r -> r.seenBy(stamp).stream())
758	                .filter(r -> r.getFromDate() == null || !r.getFromDate().isAfter(date))
759	                .max(Comparator.comparing(Rate::getFromDate, Comparator.nullsFirst(Comparator.naturalOrder())))
760	                .filter(r -> r.appliesOn(date));
761	    }
762	
763	    /** The score of a settled figure and a count of overdue claims, as the screen shows it. */
764	    private static String scoreOf(BigDecimal settled, int overdue) {
765	        return settled.movePointLeft(2).subtract(BigDecimal.valueOf(5L * overdue))
766	                .setScale(0, RoundingMode.HALF_EVEN).toPlainString();
767	    }
768	
769	    private static BigDecimal zero() {
770	        return BigDecimal.ZERO.setScale(2);
771	    }
772	
773	    /** Each figure with two decimals. */
774	    private static Map<String, String> shownAll(Map<String, BigDecimal> values) {
775	        Map<String, String> shown = new TreeMap<>();
776	        values.forEach((key, value) -> shown.put(key, shown(value)));
777	        return shown;
778	    }
779	
780	    private static String shown(BigDecimal value) {
781	        return value.setScale(2, RoundingMode.HALF_EVEN).toPlainString();
782	    }
783	}
