1	package net.officefloor.hq.app.claim;
2	
3	import jakarta.validation.Valid;
4	import jakarta.validation.constraints.NotBlank;
5	import jakarta.validation.constraints.NotNull;
6	import jakarta.validation.constraints.Pattern;
7	import jakarta.validation.constraints.Size;
8	import java.math.BigDecimal;
9	import java.math.RoundingMode;
10	import java.time.LocalDate;
11	import java.util.LinkedHashMap;
12	import java.util.List;
13	import java.util.Map;
14	import java.util.Optional;
15	import net.officefloor.hq.app.asof.AsOfReader;
16	import net.officefloor.hq.app.sheet.Sheet;
17	import org.springframework.http.HttpStatus;
18	import org.springframework.validation.annotation.Validated;
19	import org.springframework.web.bind.annotation.GetMapping;
20	import org.springframework.web.bind.annotation.PathVariable;
21	import org.springframework.web.bind.annotation.PostMapping;
22	import org.springframework.web.bind.annotation.PutMapping;
23	import org.springframework.web.bind.annotation.RequestBody;
24	import org.springframework.web.bind.annotation.RequestHeader;
25	import org.springframework.web.bind.annotation.RequestMapping;
26	import org.springframework.web.bind.annotation.ResponseStatus;
27	import org.springframework.web.bind.annotation.RestController;
28	
29	/** The people's claims on a sheet. The signed-in user's name travels in the {@code X-User} header. */
30	@RestController
31	@RequestMapping("/api/sheets/{sheetId}")
32	@Validated
33	public class ClaimController {
34	
35	    /**
36	     * A claim as shown: the amount with two decimals, the date as yyyy-mm-dd, and the due fixed when it was
37	     * settled (null when it has none, so its due is worked out from the current rate), and who opened it;
38	     * whether the person's last statement bound it, and the due it bound it to (null: none, so n/a); and the number of
39	     * the claim it corrects (null unless it is a correction); and the date that decides how its live figures round (its
40	     * own, or a correction's corrected claim's); and its place in its person's list (a later place listed first); and
41	     * its status log, oldest first; and the date it is deferred until (null when never deferred); and how many proofs
42	     * it has; and the number of the claim it was split off (null unless it was); and the user whose open editor locks
43	     * it (null when not locked); and the last day it was reminded (null when never); and its external reference (null
44	     * when it has none); and its tags, sorted and comma separated (null when it has none); and the reason it was voided
45	     * with (null when none); and its comments, oldest first; and the bulk settle batch that settled it (null when none);
46	     * and the stamp a forward-only rate is matched against (it sees one whose forwardAfter is below it); and the day it
47	     * last went to REVIEW (null when it never did); and whether a steward waived its late charge; and how many proofs
48	     * it has of each kind, by kind (receipt, photo); and whether it is held.
49	     */
50	    public record ClaimView(Long id, Long personId, String amount, LocalDate date, String note, ClaimStatus status,
51	            String number, String settledDue, String openedBy, boolean stated, String statedDue, String corrects,
52	            LocalDate roundingDate, long listed, LocalDate dueBy, List<ClaimLogView> log, LocalDate deferredUntil,
53	            int proofs, String splitFrom, String lockedBy, boolean lateEntry, LocalDate remindedOn, String ref,
54	            String tags, String voidReason, List<ClaimCommentView> comments, Long settleBatch,
55	            List<ClaimLineView> lines, Long rateStamp, LocalDate reviewOn, boolean waived,
56	            Map<String, Integer> proofsByKind, boolean held) {
57	
58	        /** A claim with no comments or lines yet. */
59	        static ClaimView of(Claim claim, List<ClaimLog> log) {
60	            return of(claim, log, List.of(), List.of());
61	        }
62	
63	        static ClaimView of(Claim claim, List<ClaimLog> log, List<ClaimComment> comments, List<ClaimLine> lines) {
64	            return new ClaimView(claim.getId(), claim.getPersonId(),
65	                    claim.getAmount().setScale(2, RoundingMode.UNNECESSARY).toPlainString(),
66	                    claim.getDate(), claim.getNote(), claim.getStatus(), claim.getNumber(),
67	                    claim.getSettledDue() == null ? null : claim.getSettledDue().toPlainString(),
68	                    claim.getOpenedBy(), claim.isStated(),
69	                    claim.getStatedDue() == null ? null : claim.getStatedDue().toPlainString(),
70	                    claim.getCorrects(), claim.getRoundingDate(), claim.getListed(), claim.getDueBy(),
71	                    log.stream().map(ClaimLogView::of).toList(), claim.getDeferredUntil(),
72	                    claim.getProofs(), claim.getSplitFrom(), claim.getLockedBy(),
73	                    claim.isLateEntry(), claim.getRemindedOn(), claim.getRef(),
74	                    claim.getTags(), claim.getVoidReason(),
75	                    comments.stream().map(ClaimCommentView::of).toList(), claim.getSettleBatch(),
76	                    lines.stream().map(ClaimLineView::of).toList(), claim.rateStamp(), claim.getReviewOn(),
77	                    claim.isWaived(), proofsByKind(claim), claim.isHeld());
78	        }
79	
80	        private static Map<String, Integer> proofsByKind(Claim claim) {
81	            Map<String, Integer> byKind = new LinkedHashMap<>();
82	            Sheet.PROOF_KINDS.forEach(kind -> byKind.put(kind, claim.proofsOf(kind)));
83	            return byKind;
84	        }
85	    }
86	
87	    /** A line of a claim: its label, its quantity and its unit amount with two decimals. */
88	    public record ClaimLineView(String label, int qty, String unit) {
89	
90	        static ClaimLineView of(ClaimLine line) {
91	            return new ClaimLineView(line.getLabel(), line.getQty(),
92	                    line.getUnit().setScale(2, RoundingMode.UNNECESSARY).toPlainString());
93	        }
94	    }
95	
96	    /** A comment on a claim: who wrote it, the sheet's today then, and its text. */
97	    public record ClaimCommentView(String by, LocalDate date, String text) {
98	
99	        static ClaimCommentView of(ClaimComment comment) {
100	            return new ClaimCommentView(comment.getBy(), comment.getDate(), comment.getText());
101	        }
102	    }
103	
104	    /** A line of a claim's status log: the status, who changed it, the sheet's today then, and its due then (or n/a). */
105	    public record ClaimLogView(ClaimStatus status, String by, LocalDate date, String due) {
106	
107	        static ClaimLogView of(ClaimLog line) {
108	            return new ClaimLogView(line.getStatus(), line.getBy(), line.getDate(), line.getDue());
109	        }
110	    }
111	
112	    /**
113	     * An amount with up to two decimals, negative only for a correction; a missing date takes the sheet's today; the
114	     * number of the claim a correction corrects, blank for any other claim; an external reference, blank for none;
115	     * comma separated tags, blank for none.
116	     */
117	    public record ClaimRequest(
118	            @NotNull @Pattern(regexp = "\\s*-?\\d{1,10}(\\.\\d{1,2})?\\s*") String amount,
119	            LocalDate date,
120	            @Size(max = 1000) String note,
121	            @Size(max = 255) String corrects,
122	            @Size(max = 255) String ref,
123	            @Size(max = 1000) String tags) {
124	
125	        BigDecimal amountValue() {
126	            return new BigDecimal(amount.trim()).setScale(2, RoundingMode.UNNECESSARY);
127	        }
128	
129	        String correctsValue() {
130	            if (corrects == null || corrects.isBlank()) {
131	                return null;
132	            }
133	            // A sheet-wide number is written without leading zeros; a period number (P1-1, X-1) as typed.
134	            String trimmed = corrects.trim();
135	            return trimmed.matches("\\d{1,18}") ? String.valueOf(Long.parseLong(trimmed)) : trimmed;
136	        }
137	    }
138	
139	    /** The ids of the claims selected to open together. */
140	    public record BulkOpenRequest(@NotNull @Size(max = 10000) List<@NotNull Long> ids) {
141	    }
142	
143	    /** The ids of the claims selected to move together, and the person they are moved to. */
144	    public record BulkReassignRequest(@NotNull @Size(max = 10000) List<@NotNull Long> ids, @NotNull Long personId) {
145	    }
146	
147	    /** The ids of the claims selected to re-date together, and the date they are re-dated to. */
148	    public record BulkRedateRequest(@NotNull @Size(max = 10000) List<@NotNull Long> ids, @NotNull LocalDate date) {
149	    }
150	
151	    /** The ids of the claims selected to settle together. */
152	    public record BulkSettleRequest(@NotNull @Size(max = 10000) List<@NotNull Long> ids) {
153	    }
154	
155	    /** The ids of the claims selected to void together, and the reason they are voided with (blank or missing for none). */
156	    public record BulkVoidRequest(@NotNull @Size(max = 10000) List<@NotNull Long> ids, @Size(max = 255) String reason) {
157	    }
158	
159	    /** Lines of name,amount,date,note to add as DRAFT claims. */
160	    public record PasteRequest(@NotNull @Size(max = 1000000) String text) {
161	    }
162	
163	    /** How many claims a paste added. */
164	    public record PasteResult(int added) {
165	    }
166	
167	    private final ClaimService service;
168	    private final BulkOpenService bulkOpen;
169	    private final BulkSettleService bulkSettle;
170	    private final PasteClaimsService paste;
171	    private final BulkReassignService bulkReassign;
172	    private final BulkRedateService bulkRedate;
173	    private final BulkVoidService bulkVoid;
174	    private final AsOfReader asOf;
175	
176	    public ClaimController(ClaimService service, BulkOpenService bulkOpen, BulkSettleService bulkSettle,
177	            PasteClaimsService paste, BulkReassignService bulkReassign, BulkRedateService bulkRedate,
178	            BulkVoidService bulkVoid, AsOfReader asOf) {
179	        this.asOf = asOf;
180	        this.bulkVoid = bulkVoid;
181	        this.bulkReassign = bulkReassign;
182	        this.bulkRedate = bulkRedate;
183	        this.service = service;
184	        this.bulkOpen = bulkOpen;
185	        this.bulkSettle = bulkSettle;
186	        this.paste = paste;
187	    }
188	
189	    /** All the sheet's claims, newest first. */
190	    @GetMapping("/claims")
191	    public List<ClaimView> list(@PathVariable @NotBlank @Size(max = 100) String sheetId,
192	            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
193	        Map<Long, List<ClaimLog>> logs = service.logs(sheetId.trim());
194	        Map<Long, List<ClaimComment>> comments = service.comments(sheetId.trim());
195	        Map<Long, List<ClaimLine>> lines = service.lines(sheetId.trim());
196	        return service.list(sheetId.trim()).stream()
